        "line": "p1:L17"
      },
      {
        "group": "건강",
        "class_code": "HH_EYE_DMG",
        "category": "1",
        "raw": "심한 눈 손상성, 구분 1",
        "line": "p1:L18"
      },
      {
        "group": "건강",
        "class_code": "HH_SKIN_SENS",
        "category": "1",
        "raw": "피부 과민성, 구분 1",
        "line": "p1:L19"
      },
      {
        "group": "환경",
        "class_code": "ENV_AQ_ACUTE",
        "category": "1",
        "raw": "급성 수생환경 유해성, 구분 1",
        "line": "p1:L20"
      },
      {
        "group": "환경",
        "class_code": "ENV_AQ_CHRONIC",
        "category": "1",
        "raw": "만성 수생환경 유해성, 구분 1",
        "line": "p1:L21"
      }
    ],
    "signal_word": "위험",
    "pictograms": [
      {
        "code": "GHS05"
      },
      {
        "code": "GHS07"
      },
      {
        "code": "GHS09"
      }
    ],
    "h_statements": [
      {
        "code": "H314",
        "text": "피부에 심한 화상과 눈에 손상을 일으킴.",
        "line": "p1:L26"
      },
      {
        "code": "H318",
        "text": "눈에 심한 손상을 일으킴.",
        "line": "p1:L27"
      },
      {
        "code": "H317",
        "text": "알레르기성 피부 반응을 일으킬 수 있음.",
        "line": "p1:L28"
      },
      {
        "code": "H400",
        "text": "수생생물에 매우 유독함",
        "line": "p1:L29"
      },
      {
        "code": "H410",
        "text": "장기적인 영향에 의해 수생생물에게 매우 유독함.",
        "line": "p1:L30"
      }
    ],
    "p_statements": [
      {
        "code": "P260",
        "type": "예방",
        "text": "미스트·증기·스프레이를 흡입하지 마시오.",
        "line": "p1:L33"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 취급 부위를 철저히 씻으시오.",
        "line": "p1:L34"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑·보호의·보안경·안면보호구를 착용하시오.",
        "line": "p1:L35"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "미스트·증기·스프레이의 흡입을 피하시오.",
        "line": "p1:L36"
      },
      {
        "code": "P272",
        "type": "예방",
        "text": "작업장 밖으로 오염된 의복을 반출하지 마시오.",
        "line": "p1:L37"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오.",
        "line": "p2:L4"
      },
      {
        "code": "P302+P352",
        "type": "대응",
        "text": "피부에 묻으면 다량의 물로 씻으시오.",
        "line": "p2:L6"
      },
      {
        "code": "P333+P313",
        "type": "대응",
        "text": "피부자극성 또는 홍반이 나타나면: 의학적인 조치∙조언을 구하시오.",
        "line": "p2:L7"
      },
      {
        "code": "P362+P364",
        "type": "대응",
        "text": "오염된 의복은 벗고 다시 사용 전 세척하시오.",
        "line": "p2:L8"
      },
      {
        "code": "P301+P330+P331",
        "type": "대응",
        "text": "삼켰다면 입을 씻어내시오. 토하게 하려 하지 마시오.",
        "line": "p2:L9"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부(또는 머리카락)에 묻으면: 오염된 모든 의복은 벗거나 제거하시오. 피부를 물로 씻으시오/샤워하시오.",
        "line": "p2:L10"
      },
      {
        "code": "P363",
        "type": "대응",
        "text": "재사용 전 의복을 세척하시오.",
        "line": "p2:L12"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면: 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L13"
      },
      {
        "code": "P310",
        "type": "대응",
        "text": "즉시 의료기관/의사의 진찰을 받으시오.",
        "line": "p2:L15"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "라벨의 추가 응급 치료 지시를 참고하여 적절한 처치를 하시오.",
        "line": "p2:L16"
      },
      {
        "code": "P305+P351+P338",
        "type": "대응",
        "text": "눈에 묻으면: 몇 분간 물로 조심해서 씻으시오. 가능하면 콘택트렌즈를 제거하시오. 계속 씻으시오.",
        "line": "p2:L17"
      },
      {
        "code": "P391",
        "type": "대응",
        "text": "누출물을 모으시오.",
        "line": "p2:L19"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가 있는 저장장소에 저장하시오.",
        "line": "p2:L21"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "폐기물관리법에 따라 내용물과 용기를 폐기하시오.",
        "line": "p2:L23"
      }
    ],
    "other_hazards": [
      {
        "value": "해당없음",
        "line": "p1:L31"
      }
    ]
  ,
    "nfpa": {
      "health": 3,
      "fire": 0,
      "reactivity": 2
    }
  ,
    "lines": {
      "pictograms": "p1:L23",
      "nfpa": "p1:L22"
    }
  }
,
  "narratives": [
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "가. 유해․위험성 분류:",
      "start":  "p1:L16",
      "end":    "p1:L21"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "나. 예방조치문구를 포함한 경고 표지 항목",
      "start":  "p1:L22",
      "end":    "p2:L23"
    }
  ]
,
  "extras": [
    {
      "after_item": "S2_LABEL_NOTE",
      "title_raw": "다. 유해․위험성 분류기준에 포함되지 않는 기타 유해․위험성:",
      "reason": "필드없음",
      "statements": [
        {
          "value": "해당없음"
        ,
          "line": "p1:L31"
        }
      ]
    ,
      "line": "p1:L31"
    }
  ]
}

